const pages=[["index.html","Обзор","home"],["landscape.html","Рынок","landscape"],["competitors.html","Конкуренты","competitors"],["founders.html","Опыт","founders"],["audience.html","Аудитория","audience"],["opportunities.html","Возможности","opportunities"],["ecosystem.html","Экосистема","ecosystem"],["discord-tools.html","Discord","discord-tools"],["telegram-tools.html","TG-паблик","telegram-tools"],["telegram-growth.html","TG-контент","telegram-growth"],["execution.html","Запуск","execution"],["final-report.html","Выводы","final"],["evidence.html","Доказательства","evidence"],["sources.html","Источники","sources"]];
const activePage=document.body.dataset.page||"home";
const headerHost=document.querySelector("[data-site-header]");
const footerHost=document.querySelector("[data-site-footer]");
if(headerHost){headerHost.innerHTML=`<header class="site-header"><div class="header-row"><a class="brand" href="index.html" aria-label="На главную"><span class="brand-mark">UA</span><span>COMMUNITY LAB<small>RESEARCH / 2026</small></span></a><button class="nav-toggle" type="button" aria-expanded="false" aria-controls="site-nav">Меню</button><nav class="site-nav" id="site-nav" aria-label="Основная навигация">${pages.map(([href,label,key])=>`<a href="${href}"${key===activePage?' aria-current="page"':""}>${label}</a>`).join("")}</nav><button class="summary-button" type="button" data-open-summary>Краткая выжимка</button></div></header>`}
if(footerHost){const currentIndex=pages.findIndex(([, ,key])=>key===activePage);const next=pages[(currentIndex+1)%pages.length];footerHost.innerHTML=`<footer class="site-footer"><div class="footer-row"><div><strong>Исследование цифрового сообщества 18+</strong><p>Обновлено 30 октября 2026 · основной рынок — люди, живущие в Украине</p></div><div class="footer-links"><a href="sources.html">Все источники</a><a href="${next[0]}">Далее: ${next[1]} →</a></div></div></footer>`}
document.body.insertAdjacentHTML("beforeend",`<button class="summary-fab" type="button" data-open-summary aria-label="Открыть краткую выжимку">Выжимка ↗</button><dialog class="summary-dialog" id="summaryDialog" aria-labelledby="summaryTitle"><div class="dialog-head"><h2 id="summaryTitle">Краткая выжимка исследования</h2><button class="dialog-close" type="button" aria-label="Закрыть">×</button></div><div class="dialog-body"><div class="dialog-verdict">Возможность есть, но она ещё не доказана поведением: сначала нужно показать повторное участие и устойчивые связи. Большая сеть может состоять из небольших клубов, не ограничивая общий масштаб.</div><div class="dialog-grid"><article class="dialog-card"><b>Для кого</b><p>Прежде всего люди 18–34 лет, живущие в Украине. 18–24 и 25–34 проверяются как разные группы.</p></article><article class="dialog-card"><b>Новая опора</b><p>MediaTrack 2025: Telegram за неделю — 81%, Discord — 3% среди 18–70; Discord — 10% среди 18–24 и 5% среди 25–34.</p></article><article class="dialog-card"><b>Воронка</b><p>Короткое видео или Telegram → конкретное событие → участие в Discord → повторная встреча с теми же людьми.</p></article><article class="dialog-card"><b>Как устроено</b><p>Большая сеть, внутри которой работают клубы, команды, ведущие и повторяемые события.</p></article><article class="dialog-card"><b>Что удерживает</b><p>Не количество сообщений, а повторный взаимный контакт, узнавание и постепенный переход к полезной роли.</p></article><article class="dialog-card"><b>Что пока неизвестно</b><p>Конверсия Telegram → участие, возврат через 30 дней и предел нагрузки ведущего. Это нужно измерить в пилоте.</p></article><article class="dialog-card"><b>Монетизация</b><p>После подтверждения возврата: добровольная поддержка, дополнительные сезоны, билеты и цифровое оформление. Без B2B и наборов для компаний.</p></article><article class="dialog-card"><b>Главный риск</b><p>Быстрый рост без правил, ведущих и понятного пути новичка превращает сеть в шум или закрытую компанию.</p></article></div><a class="dialog-action" href="evidence.html">Открыть аудит доказательств →</a></div></dialog>`);
const dialog=document.getElementById("summaryDialog");document.querySelectorAll("[data-open-summary]").forEach(button=>button.addEventListener("click",()=>dialog.showModal()));document.querySelector(".dialog-close")?.addEventListener("click",()=>dialog.close());dialog?.addEventListener("click",event=>{const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close()});
if(new URLSearchParams(location.search).has("summary"))dialog?.showModal();
const toggle=document.querySelector(".nav-toggle"),nav=document.querySelector(".site-nav");toggle?.addEventListener("click",()=>{const open=nav.classList.toggle("open");toggle.setAttribute("aria-expanded",String(open))});
const search=document.getElementById("sourceSearch"),sourceItems=[...document.querySelectorAll(".source-item")],count=document.getElementById("sourceCount");if(search&&count){const filterSources=()=>{const query=search.value.trim().toLowerCase();let visible=0;sourceItems.forEach(item=>{const show=item.textContent.toLowerCase().includes(query);item.hidden=!show;if(show)visible++});count.textContent=`${visible} / ${sourceItems.length}`};search.addEventListener("input",filterSources);filterSources()}
